<?php
require_once __DIR__ . '/config/config.php';require_login();$s=db()->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC");$s->execute([current_user()['id']]);$orders=$s->fetchAll();$pageTitle='My orders';require __DIR__.'/includes/header.php';?>
<section class="container page-section"><div class="page-heading"><span class="eyebrow">YOUR SHOPVERSE</span><h1>My orders<span class="brand-dot">.</span></h1><p>All your orders, together in one place.</p></div>
<?php if(!$orders): ?><div class="empty-state"><div>⌂</div><h3>No orders yet</h3><p>Your next favourite find is waiting.</p><a class="btn btn-primary" href="<?= BASE_URL ?>/index.php#products">Explore products</a></div><?php else: ?><div class="orders-list"><?php foreach($orders as $o): ?><article class="order-card"><div class="order-card-top"><div><small>ORDER #SV-<?= str_pad((string)$o['id'],6,'0',STR_PAD_LEFT) ?></small><h3><?= date('d M Y',strtotime($o['created_at'])) ?></h3></div><span class="status-pill"><?= e($o['status']) ?></span></div><div class="order-card-bottom"><span><?= e($o['payment_method']==='cod'?'Cash on delivery':$o['payment_method']) ?></span><strong><?= money($o['total']) ?></strong></div><details><summary>Delivery details</summary><p><?= e($o['full_name']) ?> · <?= e($o['phone']) ?><br><?= e($o['address']) ?>, <?= e($o['city']) ?> — <?= e($o['postal_code']) ?></p><?php $is=db()->prepare("SELECT product_name,quantity,unit_price FROM order_items WHERE order_id=?");$is->execute([$o['id']]);foreach($is->fetchAll() as $it): ?><p><?= e($it['product_name']) ?> × <?= (int)$it['quantity'] ?> — <?= money($it['unit_price']*$it['quantity']) ?></p><?php endforeach; ?></details></article><?php endforeach; ?></div><?php endif; ?></section>
<?php require __DIR__.'/includes/footer.php'; ?>
